import{t as e}from"./client-BjyMxh0H.js";var t={list(){return e.get(`/notifications/channels`)},create(t){return e.post(`/notifications/channels`,t)},update(t,n){return e.put(`/notifications/channels/${t}`,n)},delete(t){return e.delete(`/notifications/channels/${t}`)},test(t){return e.post(`/notifications/channels/${t}/test`)},listHistory(t,n=50){return e.get(`/notifications/channels/${t}/history`,{params:{limit:n}})}};export{t};